MillstoneDressingPickMaker.ironStock=18; MillstoneDressingPickMaker.bronzeStock=14; MillstoneDressingPickMaker.woodStock=10; MillstoneDressingPickMaker.leatherStock=8; MillstoneDressingPickMaker.silverStock=8; MillstoneDressingPickMaker.goldStock=6; MillstoneDressingPickMaker.jewelStock=4; MillstoneDressingPickMaker.pearlStock=4
MillstoneDressingPickMaker.productStock = {}; MillstoneDressingPickMaker.buildings = {}; MillstoneDressingPickMaker.maker = nil; MillstoneDressingPickMaker.activeMaking = {}; MillstoneDressingPickMaker.totalProducts = 0; MillstoneDressingPickMaker.dayTimer = 0
function MillstoneDressingPickMaker.init() MillstoneDressingPickMaker.ironStock=18; MillstoneDressingPickMaker.bronzeStock=14; MillstoneDressingPickMaker.woodStock=10; MillstoneDressingPickMaker.leatherStock=8; MillstoneDressingPickMaker.silverStock=8; MillstoneDressingPickMaker.goldStock=6; MillstoneDressingPickMaker.jewelStock=4; MillstoneDressingPickMaker.pearlStock=4; MillstoneDressingPickMaker.productStock={}; MillstoneDressingPickMaker.buildings={}; MillstoneDressingPickMaker.maker=nil; MillstoneDressingPickMaker.activeMaking={}; MillstoneDressingPickMaker.totalProducts=0; MillstoneDressingPickMaker.dayTimer=0; print("[MillstoneDressingPickMaker] Royal Millstone Dressing Pick Maker System initialized (6 products, 4 buildings)") end
function MillstoneDressingPickMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneDressingPickMaker.maker={name=n or ("Dletnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dletnik najet: %s (spretnost: %d)",MillstoneDressingPickMaker.maker.name,s),"success") end; return true end
function MillstoneDressingPickMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneDressingPickMaker.build(id) local ok,e=MillstoneDressingPickMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneDressingPickMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneDressingPickMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneDressingPickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneDressingPickMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneDressingPickMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneDressingPickMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneDressingPickMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneDressingPickMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneDressingPickMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneDressingPickMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneDressingPickMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneDressingPickMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneDressingPickMaker.buildings==0 then return false,"Potrebna dletna delavnica" end; if not MillstoneDressingPickMaker.maker then return false,"Potreben dletnik" end; return true end
function MillstoneDressingPickMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneDressingPickMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneDressingPickMaker.ironStock=MillstoneDressingPickMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneDressingPickMaker.bronzeStock=MillstoneDressingPickMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneDressingPickMaker.woodStock=MillstoneDressingPickMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneDressingPickMaker.leatherStock=MillstoneDressingPickMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneDressingPickMaker.silverStock=MillstoneDressingPickMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneDressingPickMaker.goldStock=MillstoneDressingPickMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneDressingPickMaker.jewelStock=MillstoneDressingPickMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneDressingPickMaker.pearlStock=MillstoneDressingPickMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneDressingPickMaker.maker then t=math.max(1,t-math.floor(MillstoneDressingPickMaker.maker.skill/13)) end; table.insert(MillstoneDressingPickMaker.activeMaking,{id="millstonedressingpick_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneDressingPickMaker.completeMaking(m) local q=1.0+(MillstoneDressingPickMaker.getQualityBonus()/100); if MillstoneDressingPickMaker.maker then q=q+(MillstoneDressingPickMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneDressingPickMaker.productStock[m.productType]=(MillstoneDressingPickMaker.productStock[m.productType] or 0)+m.quantity; MillstoneDressingPickMaker.totalProducts=MillstoneDressingPickMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneDressingPickMaker.maker then MillstoneDressingPickMaker.maker.itemsMade=MillstoneDressingPickMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneDressingPickMaker.maker.skill=math.min(100,MillstoneDressingPickMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dleto izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonedressingpick.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneDressingPickMaker.update(dt) if not _G.state then return end; MillstoneDressingPickMaker.dayTimer=MillstoneDressingPickMaker.dayTimer+dt; if MillstoneDressingPickMaker.dayTimer>=30 then MillstoneDressingPickMaker.dayTimer=0; for i=#MillstoneDressingPickMaker.activeMaking,1,-1 do local m=MillstoneDressingPickMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneDressingPickMaker.completeMaking(m); table.remove(MillstoneDressingPickMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneDressingPickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneDressingPickMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneDressingPickMaker.getStats() return {ironStock=MillstoneDressingPickMaker.ironStock,bronzeStock=MillstoneDressingPickMaker.bronzeStock,woodStock=MillstoneDressingPickMaker.woodStock,leatherStock=MillstoneDressingPickMaker.leatherStock,silverStock=MillstoneDressingPickMaker.silverStock,goldStock=MillstoneDressingPickMaker.goldStock,jewelStock=MillstoneDressingPickMaker.jewelStock,pearlStock=MillstoneDressingPickMaker.pearlStock,productStock=MillstoneDressingPickMaker.productStock,numBuildings=#MillstoneDressingPickMaker.buildings,hasMaker=MillstoneDressingPickMaker.maker~=nil,makerName=MillstoneDressingPickMaker.maker and MillstoneDressingPickMaker.maker.name or "—",makerSkill=MillstoneDressingPickMaker.maker and MillstoneDressingPickMaker.maker.skill or 0,activeMaking=#MillstoneDressingPickMaker.activeMaking,totalProducts=MillstoneDressingPickMaker.totalProducts} end
return MillstoneDressingPickMaker
